  // -----------------------------
  const p1 = $('PILAR_1').first().json.turnosDisponibles || [];
  const p2 = $('PILAR_2').first().json.turnosDisponibles || [];
  const p3 = $('PILAR_3').first().json.turnosDisponibles || [];

  const allTurnos = [...p1, ...p2, ...p3];

  // -----------------------------
  // 2. ORDEN FIJO DE CALENDARIOS
  // -----------------------------
  const ordenCalendarios = [
    "c_8ab99563c0dfff9f0439fa1e6f821c1643ad7d4ab79365c9c5df92d6375b68cc@group.calendar.google.com",
    "c_f0be89237de4c8602d7128f31fa4e7fdf3d0c4a234af529bf1a2b92ebe9136db@group.calendar.google.com",
    "c_05d2d8a02f7e9fe578ac3682550deac4dbc5dd6f0749ee0c8abc8e06257ce99d@group.calendar.google.com"
  ];

  // -----------------------------
  // 3. GENERAR ID ÚNICO
  // -----------------------------
  function generarId() {
    return (
      Date.now().toString(36) +
      Math.random().toString(36).substring(2, 8)
    ).toUpperCase();
  }

  // -----------------------------
  // 4. TOMAR EXACTAMENTE 1 TURNO POR CALENDARIO
  // -----------------------------
  function pickExactamenteUnoPorCalendario(turnos) {
    const resultado = [];

    for (const calendarId of ordenCalendarios) {
      const turno = turnos.find(
        t => t.Id_Calendario === calendarId
      );

      if (!turno) continue;

      resultado.push({
        idTurno: generarId(),
        dia: turno.dia,
        inicio: turno.horarioLlegada,
        final: turno.horarioEntrega,
        Id_Calendario: turno.Id_Calendario,
        fechaFormato: turno.fechaFormato
      });
    }

    // 🔒 blindaje final: nunca más de 3
    return resultado.slice(0, 3);
  }

  // -----------------------------
  // 5. RESPUESTA FINAL
  // -----------------------------
  return [
    {
      json: {
        turnos: pickExactamenteUnoPorCalendario(allTurnos)
      }
    }
  ];
})();

