return (() => {
  // -----------------------------
  // 0. OBTENER PATENTE DESDE EL NODO “When Executed by Another Workflow”
  // -----------------------------
  const input = $('When Executed by Another Workflow').first().json;
  const data = JSON.parse(input.query); // Convierte el texto JSON en objeto
  const patente = data[0]?.patente || 'SIN_PATENTE';

  // -----------------------------
  // 1. OBTENER TURNOS DE LOS TRES PILARES
  // -----------------------------
  const p1 = $('PILAR_1').first().json.turnosDisponibles || [];
  const p2 = $('PILAR_2').first().json.turnosDisponibles || [];
  const p3 = $('PILAR_3').first().json.turnosDisponibles || [];

  const allTurnos = [...p1, ...p2, ...p3];

  // -----------------------------
  // 2. FUNCIÓN PARA GENERAR ID ÚNICO ALEATORIO
  // -----------------------------
  function generarId() {
    return (
      Date.now().toString(36) +
      Math.random().toString(36).substring(2, 8)
    ).toUpperCase();
  }

  // -----------------------------
  // 3. FUNCIÓN PARA SELECCIONAR HASTA 16 TURNOS
  // -----------------------------
  function pick(arr) {
    const result = [];
    const days = [...new Set(arr.map(t => t.dia))];

    while (result.length < 16 && days.length > 0) {
      const d = days.splice(Math.floor(Math.random() * days.length), 1)[0];
      const options = arr.filter(t => t.dia === d);
      if (options.length > 0) {
        const chosen = options[Math.floor(Math.random() * options.length)];
        result.push(chosen);
      }
    }

    while (result.length < 16) {
      const remaining = arr.filter(
        t => !result.some(r => r.dia === t.dia && r.horarioLlegada === t.horarioLlegada)
      );
      if (remaining.length === 0) break;
      const chosen = remaining[Math.floor(Math.random() * remaining.length)];
      result.push(chosen);
    }

    // -----------------------------
    // 4. FORMATO FINAL PARA EL AGENTE (con idTurno y patente)
    // -----------------------------
    return result.map(t => ({
      idTurno: generarId(),
      dia: t.dia,
      inicio: t.horarioLlegada,
      final: t.horarioEntrega,
      Id_Calendario: t.Id_Calendario,
      fechaFormato: t.fechaFormato,
      patente // 👈 se agrega aquí
    }));
  }

  // -----------------------------
  // 5. RESPUESTA FINAL
  // -----------------------------
  return [
    {
      json: {
        turnos: pick(allTurnos)
      }
    }
  ];
})();

